def card(cid,term,lc,ln,ipa,et,poetic,scene,q,definition,usage,culture,comps,tags,rels,ids,a,b,c,alt,sc):
 return {'schema_version':'1.1.0','card_id':cid,'concept_version':'1.0.0','status':'REVIEW_READY','term':{'original':term,'language_code':lc,'language_name':ln,'ipa':ipa},'experience_type':et,'front':{'poetic_line':poetic,'scene':scene,'reflection_question':q},'meaning':{'verified_definition':definition,'usage_context':usage,'cultural_context':culture},'comparisons':comps,'semantic_tags':tags,'relations':rels,'reference_ids':ids,'verification':{'status':'VERIFIED','last_reviewed_at':TODAY,'lexical_source_count':1,'scholarly_source_count':sc},'assets':{'illustration_asset_id':a,'share_asset_id':b,'audio_asset_id':c,'alt_text':alt}}
